Get-WinEvent -FilterHashtable @{
  LogName='Security'
  Id=1102
  StartTime=(Get-Date).AddDays(-7)
} -MaxEvents 100 | Select-Object TimeCreated,Id,RecordId,Message

Get-WinEvent -FilterHashtable @{
  LogName='System'
  Id=104
  StartTime=(Get-Date).AddDays(-7)
} -MaxEvents 100 | Select-Object TimeCreated,ProviderName,Id,Message
